import{_ as a,o as n,c as t,a2 as e}from"./chunks/framework.BC3NdntU.js";const c=JSON.parse('{"title":"11.6 提示词工程(上):指令与结构","description":"","frontmatter":{},"headers":[],"relativePath":"卷十一-AIAgentHarness与提示词工程/11.6-提示词工程上-指令与结构.md","filePath":"卷十一-AIAgentHarness与提示词工程/11.6-提示词工程上-指令与结构.md","lastUpdated":1788782623000}'),i={name:"卷十一-AIAgentHarness与提示词工程/11.6-提示词工程上-指令与结构.md"};function o(r,s,l,p,u,d){return n(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="_11-6-提示词工程-上-指令与结构" tabindex="-1">11.6 提示词工程(上):指令与结构 <a class="header-anchor" href="#_11-6-提示词工程-上-指令与结构" aria-label="Permalink to &quot;11.6 提示词工程(上):指令与结构&quot;">​</a></h1><blockquote><p>卷:卷十一 · AI Agent Harness 与提示词工程 难度:⭐⭐ 进阶 | 阅读时间:25min</p></blockquote><hr><h2 id="引言-提示词-把-意图-约束-写进上下文的输入" tabindex="-1">引言:提示词 = 把&quot;意图 + 约束&quot;写进上下文的输入 <a class="header-anchor" href="#引言-提示词-把-意图-约束-写进上下文的输入" aria-label="Permalink to &quot;引言:提示词 = 把&quot;意图 + 约束&quot;写进上下文的输入&quot;">​</a></h2><p>提示词工程(Prompt Engineering)不是&quot;会写套话&quot;,而是<strong>用结构化方式,把任务、约束、格式讲清楚,引导模型输出你想要的东西</strong>。上半部分讲&quot;指令与结构&quot;,下半部分(11.7)讲&quot;推理增强&quot;。</p><hr><h2 id="一、一个好提示词的结构骨架" tabindex="-1">一、一个好提示词的结构骨架 <a class="header-anchor" href="#一、一个好提示词的结构骨架" aria-label="Permalink to &quot;一、一个好提示词的结构骨架&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 角色(Role):你是谁,以什么视角做事</span></span>
<span class="line"><span>② 任务(Task):要做什么,目标是什么</span></span>
<span class="line"><span>③ 上下文(Context):必要的背景、约束条件</span></span>
<span class="line"><span>④ 约束(Constraints):边界——不许做什么、格式要求</span></span>
<span class="line"><span>⑤ 输出格式(Output):结果长什么样(JSON/表格/步骤)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">你是资深前端工程师(角色)。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">帮我审查下面这段代码的性能问题(任务)。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">背景:这是一个 Vue3 项目,目标浏览器是移动端(上下文)。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">要求:只指出问题,不直接改代码;每条给出&quot;问题-原因-建议&quot;(约束)。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">输出:Markdown 表格,列为【问题|原因|建议】(输出格式)。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><hr><h2 id="二、指令遵循的四个要点" tabindex="-1">二、指令遵循的四个要点 <a class="header-anchor" href="#二、指令遵循的四个要点" aria-label="Permalink to &quot;二、指令遵循的四个要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要点</th><th>说明</th><th>反例</th></tr></thead><tbody><tr><td><strong>具体</strong></td><td>越具体,越可控</td><td>&quot;写点东西&quot; ❌</td></tr><tr><td><strong>给边界</strong></td><td>明确&quot;不要做什么&quot;</td><td>只说不许废话,没说长度</td></tr><tr><td><strong>给格式</strong></td><td>指定输出结构</td><td>期望 JSON 却没说</td></tr><tr><td><strong>给示例</strong></td><td>few-shot 示范</td><td>任务新颖却零示例</td></tr></tbody></table><blockquote><p>一个反直觉的经验:<strong>约束(negative)往往比指令(positive)更能压住幻觉</strong>——&quot;不要编造 API,不知道就说不知道&quot;这类&quot;负面指令&quot;很关键(呼应 11.1 的幻觉)。</p></blockquote><hr><h2 id="三、输出格式约束-让结果-可解析" tabindex="-1">三、输出格式约束:让结果&quot;可解析&quot; <a class="header-anchor" href="#三、输出格式约束-让结果-可解析" aria-label="Permalink to &quot;三、输出格式约束:让结果&quot;可解析&quot;&quot;">​</a></h2><p>Agent 场景里,模型的输出经常要被<strong>程序解析</strong>。所以要:</p><ol><li><strong>指定格式</strong>:JSON、XML、Markdown、或自定义标记</li><li><strong>配低温</strong>(11.1):降低随机性,提高格式稳定</li><li><strong>用工具的 JSON Schema 硬约束</strong>(11.5):函数调用的结构化输出是最稳的</li></ol><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">只输出一个 JSON 对象,不要任何其他文字:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{&quot;result&quot;: &quot;通过/不通过&quot;, &quot;reason&quot;: &quot;一句话原因&quot;}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><blockquote><p>原则:<strong>凡是下游要解析的输出,都要锁格式</strong>——口头&quot;大概输出个 JSON&quot;一定会翻车。</p></blockquote><hr><h2 id="四、few-shot-用示例-编程-行为" tabindex="-1">四、few-shot:用示例&quot;编程&quot;行为 <a class="header-anchor" href="#四、few-shot-用示例-编程-行为" aria-label="Permalink to &quot;四、few-shot:用示例&quot;编程&quot;行为&quot;">​</a></h2><p>不给模型改权重,只靠<strong>在上下文里放示例</strong>,就能教会它格式与风格(11.1 的上下文学习):</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">把句子分类为&quot;正面/负面&quot;:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;太棒了&quot; → 正面</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;真烂&quot; → 负面</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;还行吧&quot; →           ← 模型按示例模式补出&quot;中性/正面&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>few-shot 的三个技巧:</strong></p><ul><li>示例要<strong>覆盖边界情况</strong>(正面、负面、中性都来一个)</li><li>示例与目标任务<strong>格式严格一致</strong></li><li>示例不是越多越好:<strong>关键示例 &gt; 一堆平庸示例</strong></li></ul><hr><h2 id="五、小结" tabindex="-1">五、小结 <a class="header-anchor" href="#五、小结" aria-label="Permalink to &quot;五、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>提示词结构:角色 + 任务 + 上下文 + 约束 + 输出格式</span></span>
<span class="line"><span>指令遵循:具体 / 给边界(负面约束压幻觉)/ 给格式 / 给示例</span></span>
<span class="line"><span>输出格式:JSON 化 + 低温 + 结构化输出;要解析必锁格式</span></span>
<span class="line"><span>few-shot:示例即&quot;上下文里的编程&quot;,覆盖边界、格式一致</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><hr><h2 id="六、思考题" tabindex="-1">六、思考题 <a class="header-anchor" href="#六、思考题" aria-label="Permalink to &quot;六、思考题&quot;">​</a></h2><p><strong>Q1:为什么&quot;负面约束&quot;(&quot;不要编造&quot;&quot;不知道就说不知道&quot;)很重要?</strong></p><p>因为模型是&quot;概率补全&quot;而非&quot;查库&quot;,默认倾向<strong>给一个看似合理的答案</strong>(幻觉)。正面指令告诉它&quot;做什么&quot;,负面约束告诉它&quot;<strong>做不出来的边界在哪</strong>&quot;,能显著抑制它在没把握时乱编。这是提示词工程里最被低估的一类。</p><p><strong>Q2:让模型稳定输出 JSON,有哪些手段?</strong></p><p>① 提示里<strong>明确指定</strong> JSON 结构与字段;② 调<strong>低 temperature</strong>(降低随机);③ 用<strong>结构化输出/函数调用</strong>的 schema 硬约束(最稳);④ few-shot 给 JSON 示例;⑤ 解析失败时<strong>把错误喂回重试</strong>(11.3)。</p><hr><p>📎 参考:OpenAI Prompt Engineering Guide、Anthropic Prompt Engineering 文档</p>`,36)])])}const g=a(i,[["render",o]]);export{c as __pageData,g as default};
